//! Conversion of Unicode scalar value ranges into sequences of byte ranges
//! that recognise exactly the UTF-8 encodings of those scalar values.
//!
//! This lets the byte-oriented NFA match Unicode character classes without ever
//! decoding: a class becomes an alternation of byte-range sequences.

/// One byte range, inclusive on both ends.
#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct ByteRange {
    pub start: u8,
    pub end: u8,
}

impl ByteRange {
    fn new(start: u8, end: u8) -> Self {
        ByteRange { start, end }
    }
}

/// A sequence of byte ranges: matches one byte against each range, in order.
pub type Utf8Seq = Vec<ByteRange>;

const MAX_1: u32 = 0x7F;
const MAX_2: u32 = 0x7FF;
const MAX_3: u32 = 0xFFFF;

fn encoded_len(cp: u32) -> usize {
    if cp <= MAX_1 {
        1
    } else if cp <= MAX_2 {
        2
    } else if cp <= MAX_3 {
        3
    } else {
        4
    }
}

fn encode(cp: u32) -> ([u8; 4], usize) {
    let mut buf = [0u8; 4];
    let n = encoded_len(cp);
    match n {
        1 => buf[0] = cp as u8,
        2 => {
            buf[0] = 0xC0 | (cp >> 6) as u8;
            buf[1] = 0x80 | (cp & 0x3F) as u8;
        }
        3 => {
            buf[0] = 0xE0 | (cp >> 12) as u8;
            buf[1] = 0x80 | ((cp >> 6) & 0x3F) as u8;
            buf[2] = 0x80 | (cp & 0x3F) as u8;
        }
        _ => {
            buf[0] = 0xF0 | (cp >> 18) as u8;
            buf[1] = 0x80 | ((cp >> 12) & 0x3F) as u8;
            buf[2] = 0x80 | ((cp >> 6) & 0x3F) as u8;
            buf[3] = 0x80 | (cp & 0x3F) as u8;
        }
    }
    (buf, n)
}

/// Produce the byte-range sequences recognising the UTF-8 encodings of every
/// scalar value in `start..=end`.
pub fn utf8_sequences(start: u32, end: u32) -> Vec<Utf8Seq> {
    let mut out = Vec::new();
    split(start, end, &mut out);
    out
}

fn split(start: u32, end: u32, out: &mut Vec<Utf8Seq>) {
    if start > end {
        return;
    }
    // Ranges spanning different encoded lengths must be handled separately.
    for &max in &[MAX_1, MAX_2, MAX_3] {
        if start <= max && max < end {
            split(start, max, out);
            split(max + 1, end, out);
            return;
        }
    }
    // Surrogate code points are not scalar values.
    if start < 0xE000 && end > 0xD7FF {
        split(start, 0xD7FF, out);
        split(0xE000, end, out);
        return;
    }

    let n = encoded_len(start);
    debug_assert_eq!(n, encoded_len(end));

    if n == 1 {
        out.push(vec![ByteRange::new(start as u8, end as u8)]);
        return;
    }

    // Split so that every trailing continuation byte covers either its full
    // 0x80..=0xBF range or a single fixed value shared by both ends.
    for i in (1..n).rev() {
        let mask: u32 = (1u32 << (6 * i)) - 1;
        if (start & !mask) != (end & !mask) {
            if (start & mask) != 0 {
                split(start, start | mask, out);
                split((start | mask) + 1, end, out);
                return;
            }
            if (end & mask) != mask {
                split(start, (end & !mask) - 1, out);
                split(end & !mask, end, out);
                return;
            }
        }
    }

    let (sb, _) = encode(start);
    let (eb, _) = encode(end);
    let mut seq = Vec::with_capacity(n);
    for i in 0..n {
        seq.push(ByteRange::new(sb[i], eb[i]));
    }
    out.push(seq);
}

/// A prefix-shared tree of byte-range sequences. Sharing the first range keeps
/// the compiled program small for classes with many scalar ranges.
pub enum SeqTree {
    /// Terminal: the sequence ends here.
    End,
    /// Match one byte in `range`, then continue with `next`.
    Branch(Vec<(ByteRange, SeqTree)>),
}

pub fn build_tree(seqs: &[Utf8Seq]) -> SeqTree {
    build_tree_at(seqs, 0)
}

fn build_tree_at(seqs: &[&[ByteRange]], _depth: usize) -> SeqTree
where
{
    unreachable!()
}

/// Group sequences by their leading byte range, recursively.
fn group(seqs: Vec<&[ByteRange]>) -> SeqTree {
    if seqs.iter().any(|s| s.is_empty()) {
        return SeqTree::End;
    }
    let mut branches: Vec<(ByteRange, Vec<&[ByteRange]>)> = Vec::new();
    for s in seqs {
        let head = s[0];
        let tail = &s[1..];
        match branches.iter_mut().find(|(r, _)| *r == head) {
            Some((_, rest)) => rest.push(tail),
            None => branches.push((head, vec![tail])),
        }
    }
    SeqTree::Branch(
        branches
            .into_iter()
            .map(|(r, rest)| {
                let sub = if rest.iter().all(|s| s.is_empty()) {
                    SeqTree::End
                } else {
                    group(rest)
                };
                (r, sub)
            })
            .collect(),
    )
}

pub fn tree_from(seqs: &[Utf8Seq]) -> SeqTree {
    if seqs.is_empty() {
        return SeqTree::Branch(Vec::new());
    }
    group(seqs.iter().map(|s| s.as_slice()).collect())
}

