//! Most sets are derived at run time from `char`'s own Unicode tables, which
//! keeps this module small and avoids shipping generated data. The handful of
//! properties `char` does not expose are listed explicitly.

/// An inclusive range of scalar values.
pub type CharRange = (u32, u32);

/// Build a range set by testing every scalar value with `pred`.
fn scan(pred: impl Fn(char) -> bool) -> Vec<CharRange> {
    let mut out: Vec<CharRange> = Vec::new();
    let mut cur: Option<(u32, u32)> = None;
    for cp in 0u32..=0x10FFFF {
        let is = match char::from_u32(cp) {
            Some(c) => pred(c),
            // Surrogates belong to Cs; no property we support includes them.
            None => false,
        };
        match (is, cur) {
            (true, Some((s, e))) if e + 1 == cp => cur = Some((s, cp)),
            (true, Some((s, e))) => {
                out.push((s, e));
                cur = Some((cp, cp));
            }
            (true, None) => cur = Some((cp, cp)),
            (false, _) => {
                if let Some(r) = cur.take() {
                    out.push(r);
                }
            }
        }
    }
    if let Some(r) = cur {
        out.push(r);
    }
    out
