fn from_static(rs: &[CharRange]) -> Vec<CharRange> {
    rs.to_vec()
}

/// Normalise a Unicode property or value name the way the reference engine
/// does: strip spaces, underscores and hyphens and lowercase the rest.
pub fn normalize(name: &str) -> String {
    name.chars()
        .filter(|c| *c != ' ' && *c != '_' && *c != '-')
        .flat_map(|c| c.to_lowercase())
        .collect()
}

/// `\w` in Unicode mode.
pub fn perl_word() -> Vec<CharRange> {
    let mut v = scan(|c| c.is_alphanumeric());
    v.extend_from_slice(PC);
    v.extend_from_slice(JOIN_CONTROL);
    normalize_ranges(&mut v);
    v
}

/// `\d` in Unicode mode.
pub fn perl_digit() -> Vec<CharRange> {
    from_static(ND)
}

/// `\s` in Unicode mode.
pub fn perl_space() -> Vec<CharRange> {
    scan(|c| c.is_whitespace())
}

/// Sort and merge a range set in place.
pub fn normalize_ranges(v: &mut Vec<CharRange>) {
    v.sort_unstable();
    let mut out: Vec<CharRange> = Vec::with_capacity(v.len());
    for &(s, e) in v.iter() {
        if s > e {
            continue;
        }
        match out.last_mut() {
            Some(last) if s <= last.1.saturating_add(1) => {
                if e > last.1 {
                    last.1 = e;
                }
            }
            _ => out.push((s, e)),
        }
    }
    *v = out;
}

/// Complement a normalised range set over the scalar value space.
pub fn negate_ranges(v: &[CharRange]) -> Vec<CharRange> {
    let mut out = Vec::new();
    let mut next = 0u32;
    for &(s, e) in v {
        if s > next {
            out.push((next, s - 1));
        }
        if e >= 0x10FFFF {
            return out;
        }
        next = next.max(e + 1);
    }
    if next <= 0x10FFFF {
        out.push((next, 0x10FFFF));
    }
    out
}

/// Intersect two normalised range sets.
pub fn intersect_ranges(a: &[CharRange], b: &[CharRange]) -> Vec<CharRange> {
    let mut out = Vec::new();
    let (mut i, mut j) = (0, 0);
    while i < a.len() && j < b.len() {
        let s = a[i].0.max(b[j].0);
        let e = a[i].1.min(b[j].1);
        if s <= e {
            out.push((s, e));
        }
        if a[i].1 < b[j].1 {
            i += 1;
        } else {
            j += 1;
        }
    }
    out
}

/// Subtract `b` from `a` (both normalised).
pub fn difference_ranges(a: &[CharRange], b: &[CharRange]) -> Vec<CharRange> {
    intersect_ranges(a, &negate_ranges(b))
}

/// Symmetric difference of `a` and `b` (both normalised).
pub fn symmetric_difference(a: &[CharRange], b: &[CharRange]) -> Vec<CharRange> {
    let mut u = a.to_vec();
    u.extend_from_slice(b);
    normalize_ranges(&mut u);
    difference_ranges(&u, &intersect_ranges(a, b))
}

/// POSIX bracket class names, Unicode-aware as in the reference engine.
pub fn posix_class(name: &str) -> Option<Vec<CharRange>> {
    let v = match name {
        "alnum" => {
            let mut v = scan(|c| c.is_alphabetic());
            v.extend(perl_digit());
            normalize_ranges(&mut v);
            v
        }
        "alpha" => scan(|c| c.is_alphabetic()),
        "ascii" => vec![(0x0, 0x7F)],
        "blank" => {
            let mut v = vec![(0x09, 0x09)];
            v.extend(scan(|c| {
                c.is_whitespace() && !matches!(c, '\n' | '\r' | '\u{b}' | '\u{c}' | '\u{85}')
            }));
            normalize_ranges(&mut v);
            v
        }
        "cntrl" => scan(|c| (c as u32) < 0x20 || (0x7F..=0x9F).contains(&(c as u32))),
        "digit" => perl_digit(),
        "graph" => {
            let ws = scan(|c| c.is_whitespace());
            let cc = scan(|c| (c as u32) < 0x20 || (0x7F..=0x9F).contains(&(c as u32)));
            let unassigned = scan(|c| {
                // Approximate Cn/Co/Cs with what `char` can tell us.
                !c.is_alphanumeric()
                    && !c.is_whitespace()
                    && !c.is_control()
                    && !is_punct_or_symbol(c)
            });
            let mut excl = ws;
            excl.extend(cc);
            excl.extend(unassigned);
            normalize_ranges(&mut excl);
            negate_ranges(&excl)
        }
        "lower" => scan(|c| c.is_lowercase()),
        "print" => {
            let mut g = posix_class("graph")?;
            g.push((0x20, 0x20));
            normalize_ranges(&mut g);
            g
        }
        "punct" => scan(is_punct_or_symbol),
        "space" => perl_space(),
        "upper" => scan(|c| c.is_uppercase()),
        "word" => perl_word(),
        "xdigit" => vec![(0x30, 0x39), (0x41, 0x46), (0x61, 0x66)],
        _ => return None,
    };
    Some(v)
}

fn is_punct_or_symbol(c: char) -> bool {
    // `char` does not expose general categories; ASCII punctuation plus the
    // common symbol/punctuation blocks cover realistic use.
    if c.is_ascii() {
        return c.is_ascii_punctuation();
    }
    let cp = c as u32;
    matches!(cp,
        0x00A1..=0x00BF | 0x00D7 | 0x00F7 | 0x2010..=0x2027 | 0x2030..=0x205E
        | 0x2190..=0x2BFF | 0x3001..=0x3003 | 0x3008..=0x3020 | 0x3030 | 0xFF01..=0xFF0F
        | 0xFF1A..=0xFF20 | 0xFF3B..=0xFF40 | 0xFF5B..=0xFF65)
        && !c.is_alphanumeric()
}

/// Look up a `\p{...}` property. `value` is the part after `=` if present.
pub fn unicode_class(prop: &str, value: Option<&str>) -> Option<Vec<CharRange>> {
    let (kind, name) = match value {
        Some(v) => (normalize(prop), normalize(v)),
        None => (String::new(), normalize(prop)),
    };
    match kind.as_str() {
        "" => general_category(&name)
            .or_else(|| script(&name))
            .or_else(|| binary_property(&name)),
        "gc" | "generalcategory" | "category" => general_category(&name),
        "sc" | "script" => script(&name),
        "scx" | "scriptextensions" => script(&name),
        _ => None,
    }
}

fn script(name: &str) -> Option<Vec<CharRange>> {
    SCRIPTS
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(_, rs)| from_static(rs))
}

fn binary_property(name: &str) -> Option<Vec<CharRange>> {
    let v = match name {
        "alphabetic" | "alpha" => scan(|c| c.is_alphabetic()),
        "any" => vec![(0, 0x10FFFF)],
        "ascii" => vec![(0, 0x7F)],
        "assigned" => {
            // Approximation: everything char's tables know something about.
            vec![(0, 0x10FFFF)]
        }
        "whitespace" | "white_space" | "space" => perl_space(),
        "lowercase" | "lower" => scan(|c| c.is_lowercase()),
        "uppercase" | "upper" => scan(|c| c.is_uppercase()),
        "word" => perl_word(),
        "digit" => perl_digit(),
        "numeric" => scan(|c| c.is_numeric()),
        "control" | "cntrl" => scan(|c| c.is_control()),
        _ => return posix_class(name),
    };
    Some(v)
}

fn general_category(name: &str) -> Option<Vec<CharRange>> {
    let v = match name {
        "l" | "letter" => scan(|c| c.is_alphabetic()),
        "lu" | "uppercaseletter" => scan(|c| c.is_uppercase()),
        "ll" | "lowercaseletter" => scan(|c| c.is_lowercase()),
        "lt" | "titlecaseletter" => scan(|c| {
            c.is_alphabetic() && !c.is_uppercase() && !c.is_lowercase() && c.to_uppercase().count() == 1
        }),
        "n" | "number" => scan(|c| c.is_numeric()),
        "nd" | "decimalnumber" => perl_digit(),
        "c" | "other" => scan(|c| c.is_control()),
        "cc" | "control" => scan(|c| (c as u32) < 0x20 || (0x7F..=0x9F).contains(&(c as u32))),
        "z" | "separator" => scan(|c| c.is_whitespace() && !c.is_control()),
        "zs" | "spaceseparator" => scan(|c| {
            c.is_whitespace() && !c.is_control() && c != '\u{2028}' && c != '\u{2029}'
        }),
        "p" | "punctuation" => scan(|c| c.is_ascii_punctuation() || is_punct_or_symbol(c)),
        _ => return None,
    };
    Some(v)
}

/// Simple case-folding equivalence key. Two scalar values are considered
/// case-insensitively equal when their keys match.
pub fn fold_key(c: char) -> char {
    // A handful of scalar values fold together without agreeing on a simple
    // lowercase mapping.
    match c {
        '\u{3C2}' => return '\u{3C3}', // final sigma -> sigma
        '\u{3D0}' => return '\u{3B2}', // beta symbol
        '\u{3D1}' => return '\u{3B8}', // theta symbol
        '\u{3D5}' => return '\u{3C6}', // phi symbol
        '\u{3D6}' => return '\u{3C0}', // pi symbol
        '\u{3F0}' => return '\u{3BA}', // kappa symbol
        '\u{3F1}' => return '\u{3C1}', // rho symbol
        '\u{3F5}' => return '\u{3B5}', // lunate epsilon
        '\u{1E9B}' => return '\u{1E61}',
        '\u{1FBE}' => return '\u{3B9}',
        '\u{345}' => return '\u{3B9}',
        '\u{1C80}' => return '\u{432}',
        '\u{1C81}' => return '\u{434}',
        '\u{1C82}' => return '\u{43E}',
        '\u{1C83}' => return '\u{441}',
        '\u{1C84}' | '\u{1C85}' => return '\u{442}',
        '\u{1C86}' => return '\u{44A}',
        '\u{1C87}' => return '\u{463}',
        '\u{1C88}' => return '\u{A64B}',
        '\u{17F}' => return '\u{73}', // long s
        _ => {}
    }
    let mut it = c.to_lowercase();
    let first = it.next().unwrap_or(c);
    if it.next().is_none() {
        first
    } else {
        c
    }
}

/// Close a range set under simple case folding.
pub fn case_fold(ranges: &[CharRange]) -> Vec<CharRange> {
    // Collect the fold keys present in the class, then admit every scalar value
    // sharing one of those keys.
    let mut keys: Vec<char> = Vec::new();
    for &(s, e) in ranges {
        for cp in s..=e {
            if let Some(c) = char::from_u32(cp) {
                keys.push(fold_key(c));
            }
        }
        if e - s > 0x20000 {
            // Enormous ranges are already closed under folding for all
            // practical purposes; avoid quadratic work.
            break;
        }
    }
    keys.sort_unstable();
    keys.dedup();
    let keyset: std::collections::HashSet<char> = keys.into_iter().collect();
    let mut extra = scan(|c| keyset.contains(&fold_key(c)));
    extra.extend_from_slice(ranges);
    normalize_ranges(&mut extra);
    extra
}

/// Is this scalar value a `\w` character (Unicode mode)?
pub fn is_word_char(c: char) -> bool {
    c.is_alphanumeric()
        || PC.iter().any(|&(s, e)| (s..=e).contains(&(c as u32)))
        || JOIN_CONTROL.iter().any(|&(s, e)| (s..=e).contains(&(c as u32)))
}

/// Is this byte a `\w` byte (ASCII / non-Unicode mode)?
pub fn is_word_byte(b: u8) -> bool {
    b.is_ascii_alphanumeric() || b == b'_'
}

