//! Regular expression parser.
//!
//! Produces a high level intermediate representation and, on failure, an error
//! carrying the character spans needed to render a caret diagram.

use super::unicode;

/// Inclusive span over *character* indices of the pattern.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Span {
    pub start: usize,
    pub end: usize,
}

impl Span {
    fn new(start: usize, end: usize) -> Self {
        Span { start, end }
    }
    fn at(pos: usize) -> Self {
        Span { start: pos, end: pos }
    }
}

#[derive(Clone, Debug)]
pub struct ParseError {
    pub msg: String,
    pub span: Span,
    pub span2: Option<Span>,
}

impl ParseError {
    fn new(msg: impl Into<String>, span: Span) -> Self {
        ParseError { msg: msg.into(), span, span2: None }
    }
}

type Result<T> = std::result::Result<T, ParseError>;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Look {
    StartText,
    EndText,
    StartLine,
    EndLine,
    StartCrLf,
    EndCrLf,
    WordAscii,
    NotWordAscii,
    WordUnicode,
    NotWordUnicode,
    WordStartAscii,
    WordEndAscii,
    WordStartUnicode,
    WordEndUnicode,
    WordStartHalfAscii,
    WordEndHalfAscii,
    WordStartHalfUnicode,
    WordEndHalfUnicode,
}

#[derive(Clone, Debug)]
pub enum Hir {
    Empty,
    /// Literal bytes, matched one at a time.
    Literal(Vec<u8>),
    /// Set of scalar values; matched as a UTF-8 automaton.
    UnicodeClass(Vec<(u32, u32)>),
    /// Set of byte values.
    ByteClass(Vec<(u8, u8)>),
    Look(Look),
    Repeat { min: u32, max: Option<u32>, greedy: bool, sub: Box<Hir> },
    /// `index` is `None` for non-capturing groups.
    Group { index: Option<u32>, sub: Box<Hir> },
    Concat(Vec<Hir>),
    Alt(Vec<Hir>),
}

#[derive(Clone, Copy, Debug)]
pub struct Flags {
    pub case_insensitive: bool,
    pub multi_line: bool,
    pub dot_matches_new_line: bool,
    pub swap_greed: bool,
    pub ignore_whitespace: bool,
    pub unicode: bool,
    pub crlf: bool,
}

impl Default for Flags {
    fn default() -> Self {
        Flags {
            case_insensitive: false,
            multi_line: false,
            dot_matches_new_line: false,
            swap_greed: false,
            ignore_whitespace: false,
            unicode: true,
            crlf: false,
        }
    }
}

pub struct Parsed {
    pub hir: Hir,
    pub group_count: u32,
    pub names: Vec<(String, u32)>,
}

const NEST_LIMIT: usize = 250;

pub struct Parser<'a> {
    chars: Vec<char>,
    pat: &'a str,
    pos: usize,
    flags: Flags,
    next_index: u32,
    names: Vec<(String, u32, Span)>,
    nest: usize,
}

impl<'a> Parser<'a> {
    pub fn new(pat: &'a str, flags: Flags) -> Self {
        Parser {
            chars: pat.chars().collect(),
            pat,
            pos: 0,
            flags,
            next_index: 1,
            names: Vec::new(),
            nest: 0,
        }
    }

    pub fn parse(mut self) -> Result<Parsed> {
        let hir = self.parse_alternation(None)?;
        if let Some(c) = self.peek() {
            if c == ')' {
                return Err(ParseError::new("unopened group", Span::new(self.pos, self.pos + 1)));
            }
        }
        let names = self.names.iter().map(|(n, i, _)| (n.clone(), *i)).collect();
        Ok(Parsed { hir, group_count: self.next_index - 1, names })
    }

    // ----- character helpers -------------------------------------------------

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn peek_at(&self, off: usize) -> Option<char> {
        self.chars.get(self.pos + off).copied()
    }

    fn bump(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn eat(&mut self, c: char) -> bool {
        if self.peek() == Some(c) {
            self.pos += 1;
            true
        } else {
            false
        }
    }

    /// Skip whitespace and `#` comments when in verbose mode.
    fn skip_space(&mut self) {
        if !self.flags.ignore_whitespace {
            return;
        }
        loop {
            match self.peek() {
                Some(c) if c.is_whitespace() => {
                    self.pos += 1;
                }
                Some('#') => {
                    while let Some(c) = self.peek() {
                        self.pos += 1;
                        if c == '\n' {
                            break;
                        }
                    }
                }
                _ => return,
            }
        }
    }

    // ----- grammar -----------------------------------------------------------

    fn parse_alternation(&mut self, group_open: Option<usize>) -> Result<Hir> {
        let saved_flags = self.flags;
        let mut branches: Vec<Hir> = Vec::new();
        loop {
            let branch = self.parse_concat(group_open)?;
            branches.push(branch);
            self.skip_space();
            if self.eat('|') {
                continue;
            }
            break;
        }
        self.flags = saved_flags;
        if branches.len() == 1 {
            Ok(branches.pop().unwrap())
        } else {
            Ok(simplify_alt(branches))
        }
    }

    fn parse_concat(&mut self, group_open: Option<usize>) -> Result<Hir> {
        let mut items: Vec<Hir> = Vec::new();
        loop {
            self.skip_space();
            match self.peek() {
                None | Some('|') => break,
                Some(')') => {
                    if group_open.is_some() {
                        break;
                    }
                    break;
                }
                _ => {}
            }
            let start = self.pos;
            let item = self.parse_primary(group_open)?;
            match item {
                Some(h) => {
                    let h = self.parse_repeats(h, start)?;
                    push_item(&mut items, h);
                }
                // A `(?flags)` directive contributes nothing but may be
                // followed by a repetition operator, which is an error.
                None => {
                    self.skip_space();
                    if let Some(c) = self.peek() {
                        if matches!(c, '*' | '+' | '?') || (c == '{' && self.looks_like_counted()) {
                            let end = self.repeat_op_end();
                            return Err(ParseError::new(
                                "repetition operator missing expression",
                                Span::new(self.pos, end),
                            ));
                        }
                    }
                }
            }
        }
        Ok(match items.len() {
            0 => Hir::Empty,
            1 => items.pop().unwrap(),
            _ => Hir::Concat(items),
        })
    }

    fn repeat_op_end(&self) -> usize {
        match self.peek() {
            Some('{') => {
                let mut i = self.pos;
                while i < self.chars.len() && self.chars[i] != '}' {
                    i += 1;
                }
                (i + 1).min(self.chars.len())
            }
            _ => self.pos + 1,
        }
    }

    fn parse_repeats(&mut self, mut hir: Hir, start: usize) -> Result<Hir> {
        loop {
            self.skip_space();
            let op_start = self.pos;
            let (min, max) = match self.peek() {
                Some('*') => {
                    self.pos += 1;
                    (0, None)
                }
                Some('+') => {
                    self.pos += 1;
                    (1, None)
                }
                Some('?') => {
                    self.pos += 1;
                    (0, Some(1))
                }
                Some('{') if self.looks_like_counted() => {
                    self.pos += 1;
                    let (min, max) = self.parse_counted(op_start)?;
                    (min, max)
                }
                _ => return Ok(hir),
            };
            let mut greedy = !self.flags.swap_greed;
            self.skip_space();
            if self.peek() == Some('?') {
                self.pos += 1;
                greedy = !greedy;
            } else if self.peek() == Some('+') {
                // Possessive quantifiers are not supported; the reference
                // engine treats a following `+` as another repetition.
            }
            let _ = start;
            hir = Hir::Repeat { min, max, greedy, sub: Box::new(hir) };
        }
    }

    /// Does the `{` at the cursor introduce a counted repetition? The reference
    /// engine treats `{` as a literal when it is not followed by a digit or `,`.
    fn looks_like_counted(&self) -> bool {
        let mut i = self.pos + 1;
        if self.flags.ignore_whitespace {
            while i < self.chars.len() && self.chars[i].is_whitespace() {
                i += 1;
            }
        }
        matches!(self.chars.get(i), Some(c) if c.is_ascii_digit())
    }

    fn parse_counted(&mut self, brace_start: usize) -> Result<(u32, Option<u32>)> {
        self.skip_space();
        let min = self.parse_decimal(brace_start)?;
        self.skip_space();
        let max = if self.eat(',') {
            self.skip_space();
            if self.peek() == Some('}') {
                None
            } else {
                Some(self.parse_decimal(brace_start)?)
            }
        } else {
            Some(min)
        };
        self.skip_space();
        if !self.eat('}') {
            return Err(ParseError::new(
                "unclosed counted repetition",
                Span::new(brace_start, brace_start + 1),
            ));
        }
        if let Some(max) = max {
            if min > max {
                return Err(ParseError::new(
                    "invalid repetition count range, the start must be <= the end",
                    Span::new(brace_start, self.pos),
                ));
            }
        }
        Ok((min, max))
    }

    fn parse_decimal(&mut self, brace_start: usize) -> Result<u32> {
        let start = self.pos;
        while matches!(self.peek(), Some(c) if c.is_ascii_digit()) {
            self.pos += 1;
        }
        if start == self.pos {
            return Err(ParseError::new(
                "unclosed counted repetition",
                Span::new(brace_start, brace_start + 1),
            ));
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        match s.parse::<u32>() {
            Ok(n) => Ok(n),
            Err(_) => Err(ParseError::new("decimal literal invalid", Span::new(start, self.pos))),
        }
    }

    /// Parse one non-repeated element. `Ok(None)` means the element produced
    /// nothing (an inline flag directive).
    fn parse_primary(&mut self, _group_open: Option<usize>) -> Result<Option<Hir>> {
        let start = self.pos;
        let c = match self.bump() {
            Some(c) => c,
            None => return Ok(Some(Hir::Empty)),
        };
        match c {
            '(' => self.parse_group(start),
            '[' => Ok(Some(self.parse_class(start)?)),
            '.' => Ok(Some(self.dot())),
            '^' => Ok(Some(Hir::Look(if self.flags.multi_line {
                if self.flags.crlf {
                    Look::StartCrLf
                } else {
                    Look::StartLine
                }
            } else {
                Look::StartText
            }))),
            '$' => Ok(Some(Hir::Look(if self.flags.multi_line {
                if self.flags.crlf {
                    Look::EndCrLf
                } else {
                    Look::EndLine
                }
            } else {
                Look::EndText
            }))),
            '*' | '+' | '?' => Err(ParseError::new(
                "repetition operator missing expression",
                Span::new(start, self.pos),
            )),
            '{' => {
                self.pos = start;
                if self.looks_like_counted() {
                    let end = self.repeat_op_end();
                    return Err(ParseError::new(
                        "repetition operator missing expression",
                        Span::new(start, end),
                    ));
                }
                self.pos = start + 1;
                Ok(Some(self.literal_char('{')))
            }
            '\\' => {
                self.pos = start;
                self.parse_escape(false).map(Some)
            }
            c => Ok(Some(self.literal_char(c))),
        }
    }

    fn dot(&self) -> Hir {
        if self.flags.unicode {
            if self.flags.dot_matches_new_line {
                Hir::UnicodeClass(vec![(0, 0x10FFFF)])
            } else if self.flags.crlf {
                Hir::UnicodeClass(unicode::negate_ranges(&[(0x0A, 0x0A), (0x0D, 0x0D)]))
            } else {
                Hir::UnicodeClass(unicode::negate_ranges(&[(0x0A, 0x0A)]))
            }
        } else if self.flags.dot_matches_new_line {
            Hir::ByteClass(vec![(0, 0xFF)])
        } else if self.flags.crlf {
            Hir::ByteClass(vec![(0x00, 0x09), (0x0B, 0x0C), (0x0E, 0xFF)])
        } else {
            Hir::ByteClass(vec![(0x00, 0x09), (0x0B, 0xFF)])
        }
    }

    fn literal_char(&self, c: char) -> Hir {
        if self.flags.case_insensitive {
            let ranges = unicode::case_fold(&[(c as u32, c as u32)]);
            if self.flags.unicode {
                return Hir::UnicodeClass(ranges);
            }
            // Without Unicode mode only ASCII folds apply.
            let mut br = Vec::new();
            for (s, e) in ranges {
                if s < 0x80 {
                    br.push((s as u8, (e.min(0x7F)) as u8));
                }
            }
            if br.is_empty() {
                br.push((c as u32 as u8, c as u32 as u8));
            }
            return Hir::ByteClass(br);
        }
        if self.flags.unicode || (c as u32) < 0x80 {
            let mut buf = [0u8; 4];
            Hir::Literal(c.encode_utf8(&mut buf).as_bytes().to_vec())
        } else {
            // In byte mode a non-ASCII literal still stands for its UTF-8 bytes.
            let mut buf = [0u8; 4];
            Hir::Literal(c.encode_utf8(&mut buf).as_bytes().to_vec())
        }
    }

    // ----- groups ------------------------------------------------------------

    fn parse_group(&mut self, open: usize) -> Result<Option<Hir>> {
        self.nest += 1;
        if self.nest > NEST_LIMIT {
            return Err(ParseError::new(
                format!("exceed the maximum number of nested parentheses/brackets ({})", NEST_LIMIT),
                Span::new(open, self.chars.len()),
            ));
        }
        let result = self.parse_group_inner(open);
        self.nest -= 1;
        result
    }

    fn parse_group_inner(&mut self, open: usize) -> Result<Option<Hir>> {
        if self.peek() == Some('?') {
            match self.peek_at(1) {
                Some('=') | Some('!') => {
                    return Err(ParseError::new(
                        "look-around, including look-ahead and look-behind, is not supported",
                        Span::new(open, open + 3),
                    ));
                }
                Some('<') => match self.peek_at(2) {
                    Some('=') | Some('!') => {
                        return Err(ParseError::new(
                            "look-around, including look-ahead and look-behind, is not supported",
                            Span::new(open, open + 4),
                        ));
                    }
                    _ => {
                        self.pos += 2; // ?<
                        return self.parse_named_group(open);
                    }
                },
                Some('P') => match self.peek_at(2) {
                    Some('<') => {
                        self.pos += 3; // ?P<
                        return self.parse_named_group(open);
                    }
                    Some('=') => {
                        return Err(ParseError::new(
                            "backreferences are not supported",
                            Span::new(open, open + 4),
                        ));
                    }
                    _ => {
                        return Err(ParseError::new(
                            "unrecognized flag",
                            Span::new(open + 2, open + 3),
                        ));
                    }
                },
                Some('#') => {
                    // Not supported by the reference engine.
                    return Err(ParseError::new("unrecognized flag", Span::new(open + 2, open + 3)));
                }
                _ => {
                    self.pos += 1; // ?
                    return self.parse_flags_group(open);
                }
            }
        }
        // Plain capturing group.
        let index = self.next_index;
        self.next_index += 1;
        let sub = self.parse_alternation(Some(open))?;
        self.skip_space();
        if !self.eat(')') {
            return Err(ParseError::new("unclosed group", Span::new(open, open + 1)));
        }
        Ok(Some(Hir::Group { index: Some(index), sub: Box::new(sub) }))
    }

    fn parse_named_group(&mut self, open: usize) -> Result<Option<Hir>> {
        let name_start = self.pos;
        let mut name = String::new();
        loop {
            match self.peek() {
                None => {
                    return Err(ParseError::new(
                        "unclosed capture group name",
                        Span::new(name_start, self.pos),
                    ))
                }
                Some('>') => {
                    self.pos += 1;
                    break;
                }
                Some(c) => {
                    if !is_capture_char(c, name.is_empty()) {
                        return Err(ParseError::new(
                            "invalid capture group character",
                            Span::new(self.pos, self.pos + 1),
                        ));
                    }
                    name.push(c);
                    self.pos += 1;
                }
            }
        }
        if name.is_empty() {
            return Err(ParseError::new(
                "empty capture group name",
                Span::new(name_start, self.pos - 1),
            ));
        }
        let name_span = Span::new(name_start, self.pos - 1);
        if let Some((_, _, prev)) = self.names.iter().find(|(n, _, _)| *n == name) {
            let mut err = ParseError::new("duplicate capture group name", name_span);
            err.span2 = Some(*prev);
            return Err(err);
        }
        let index = self.next_index;
        self.next_index += 1;
        self.names.push((name, index, name_span));
        let sub = self.parse_alternation(Some(open))?;
        self.skip_space();
        if !self.eat(')') {
            return Err(ParseError::new("unclosed group", Span::new(open, open + 1)));
        }
        Ok(Some(Hir::Group { index: Some(index), sub: Box::new(sub) }))
    }

    fn parse_flags_group(&mut self, open: usize) -> Result<Option<Hir>> {
        let saved = self.flags;
        let mut negating = false;
        let mut seen: Vec<char> = Vec::new();
        let mut saw_any_after_neg = false;
        loop {
            let c = match self.peek() {
                None => {
                    return Err(ParseError::new(
                        "expected flag but got end of regex",
                        Span::at(self.pos),
                    ))
                }
                Some(c) => c,
            };
            match c {
                ')' => {
                    if negating && !saw_any_after_neg {
                        return Err(ParseError::new(
                            "dangling flag negation operator",
                            Span::new(self.pos - 1, self.pos),
                        ));
                    }
                    self.pos += 1;
                    // Flags apply to the remainder of the enclosing group.
                    return Ok(None);
                }
                ':' => {
                    if negating && !saw_any_after_neg {
                        return Err(ParseError::new(
                            "dangling flag negation operator",
                            Span::new(self.pos - 1, self.pos),
                        ));
                    }
                    self.pos += 1;
                    let sub = self.parse_alternation(Some(open))?;
                    self.skip_space();
                    if !self.eat(')') {
                        self.flags = saved;
                        return Err(ParseError::new("unclosed group", Span::new(open, open + 1)));
                    }
                    self.flags = saved;
                    return Ok(Some(Hir::Group { index: None, sub: Box::new(sub) }));
                }
                '-' => {
                    if negating {
                        return Err(ParseError::new(
                            "flag negation operator repeated",
                            Span::new(self.pos, self.pos + 1),
                        ));
                    }
                    negating = true;
                    self.pos += 1;
                }
                'i' | 'm' | 's' | 'U' | 'u' | 'x' | 'R' => {
                    if seen.contains(&c) {
                        return Err(ParseError::new(
                            "duplicate flag",
                            Span::new(self.pos, self.pos + 1),
                        ));
                    }
                    seen.push(c);
                    if negating {
                        saw_any_after_neg = true;
                    }
                    let on = !negating;
                    match c {
                        'i' => self.flags.case_insensitive = on,
                        'm' => self.flags.multi_line = on,
                        's' => self.flags.dot_matches_new_line = on,
                        'U' => self.flags.swap_greed = on,
                        'u' => self.flags.unicode = on,
                        'x' => self.flags.ignore_whitespace = on,
                        'R' => self.flags.crlf = on,
                        _ => unreachable!(),
                    }
                    self.pos += 1;
                }
                _ => {
                    return Err(ParseError::new(
                        "unrecognized flag",
                        Span::new(self.pos, self.pos + 1),
                    ))
                }
            }
        }
    }

    // ----- escapes -----------------------------------------------------------

    /// Parse a `\...` escape. In a class context, anchors are rejected.
    fn parse_escape(&mut self, in_class: bool) -> Result<Hir> {
        let start = self.pos;
        debug_assert_eq!(self.peek(), Some('\\'));
        self.pos += 1;
        let c = match self.bump() {
            None => {
                return Err(ParseError::new(
                    "incomplete escape sequence, reached end of pattern prematurely",
                    Span::new(start, self.pos),
                ))
            }
            Some(c) => c,
        };
        match c {
            'd' | 'D' | 's' | 'S' | 'w' | 'W' => {
                let negate = c.is_ascii_uppercase();
                let hir = self.perl_class(c.to_ascii_lowercase(), negate);
                Ok(hir)
            }
            'p' | 'P' => {
                let negate = c == 'P';
                let ranges = self.parse_unicode_class(start, negate)?;
                Ok(Hir::UnicodeClass(ranges))
            }
            'b' if !in_class => {
                if self.peek() == Some('{') {
                    return self.parse_special_word_boundary(start);
                }
                Ok(Hir::Look(if self.flags.unicode { Look::WordUnicode } else { Look::WordAscii }))
            }
            'B' if !in_class => Ok(Hir::Look(if self.flags.unicode {
                Look::NotWordUnicode
            } else {
                Look::NotWordAscii
            })),
            '<' if !in_class => Ok(Hir::Look(if self.flags.unicode {
                Look::WordStartUnicode
            } else {
                Look::WordStartAscii
            })),
            '>' if !in_class => Ok(Hir::Look(if self.flags.unicode {
                Look::WordEndUnicode
            } else {
                Look::WordEndAscii
            })),
            'A' if !in_class => Ok(Hir::Look(Look::StartText)),
            'z' if !in_class => Ok(Hir::Look(Look::EndText)),
            '1'..='9' if !in_class => Err(ParseError::new(
                "backreferences are not supported",
                Span::new(start, self.pos),
            )),
            _ => {
                self.pos = start;
                let ch = self.parse_escape_literal(in_class)?;
                Ok(self.literal_char(ch))
            }
        }
    }

    fn parse_special_word_boundary(&mut self, start: usize) -> Result<Hir> {
        // \b{start}, \b{end}, \b{start-half}, \b{end-half}
        self.pos += 1; // {
        let name_start = self.pos;
        while let Some(c) = self.peek() {
            if c == '}' {
                break;
            }
            self.pos += 1;
        }
        if self.peek() != Some('}') {
            return Err(ParseError::new(
                "unclosed special word boundary assertion",
                Span::new(start, self.pos),
            ));
        }
        let name: String = self.chars[name_start..self.pos].iter().collect();
        self.pos += 1;
        let u = self.flags.unicode;
        let look = match name.as_str() {
            "start" => {
                if u {
                    Look::WordStartUnicode
                } else {
                    Look::WordStartAscii
                }
            }
            "end" => {
                if u {
                    Look::WordEndUnicode
                } else {
                    Look::WordEndAscii
                }
            }
            "start-half" => {
                if u {
                    Look::WordStartHalfUnicode
                } else {
                    Look::WordStartHalfAscii
                }
            }
            "end-half" => {
                if u {
                    Look::WordEndHalfUnicode
                } else {
                    Look::WordEndHalfAscii
                }
            }
            _ => {
                return Err(ParseError::new(
                    "unrecognized special word boundary assertion",
                    Span::new(name_start, self.pos - 1),
                ))
            }
        };
        Ok(Hir::Look(look))
    }

    /// Parse an escape that denotes a single scalar value.
    fn parse_escape_literal(&mut self, in_class: bool) -> Result<char> {
        let start = self.pos;
        self.pos += 1; // backslash
        let c = match self.bump() {
            None => {
                return Err(ParseError::new(
                    "incomplete escape sequence, reached end of pattern prematurely",
                    Span::new(start, self.pos),
                ))
            }
            Some(c) => c,
        };
        match c {
            'a' => Ok('\x07'),
            'f' => Ok('\x0C'),
            't' => Ok('\t'),
            'n' => Ok('\n'),
            'r' => Ok('\r'),
            'v' => Ok('\x0B'),
            '0' => Ok('\0'),
            'x' => self.parse_hex(start, 2),
            'u' => self.parse_hex(start, 4),
            'U' => self.parse_hex(start, 8),
            c if !c.is_alphanumeric() => Ok(c),
            _ => {
                if in_class {
                    Err(ParseError::new(
                        "invalid escape sequence found in character class",
                        Span::new(start, self.pos),
                    ))
                } else {
                    Err(ParseError::new(
                        "unrecognized escape sequence",
                        Span::new(start, self.pos),
                    ))
                }
            }
        }
    }

    fn parse_hex(&mut self, esc_start: usize, width: usize) -> Result<char> {
        if self.peek() == Some('{') {
            self.pos += 1;
            let start = self.pos;
            while let Some(c) = self.peek() {
                if c == '}' {
                    break;
                }
                self.pos += 1;
            }
            if self.peek() != Some('}') {
                return Err(ParseError::new(
                    "hexadecimal literal invalid",
                    Span::new(esc_start, self.pos),
                ));
            }
            let digits: String = self.chars[start..self.pos].iter().collect();
            self.pos += 1;
            if digits.is_empty() {
                return Err(ParseError::new(
                    "hexadecimal literal empty",
                    Span::new(start, start),
                ));
            }
            for (i, ch) in digits.chars().enumerate() {
                if !ch.is_ascii_hexdigit() {
                    return Err(ParseError::new(
                        "invalid hexadecimal digit",
                        Span::new(start + i, start + i + 1),
                    ));
                }
            }
            let n = u32::from_str_radix(&digits, 16).map_err(|_| {
                ParseError::new("hexadecimal literal invalid", Span::new(esc_start, self.pos))
            })?;
            return char::from_u32(n).ok_or_else(|| {
                ParseError::new(
                    "hexadecimal literal is not a Unicode scalar value",
                    Span::new(start, self.pos - 1),
                )
            });
        }
        let start = self.pos;
        let mut digits = String::new();
        for _ in 0..width {
            match self.peek() {
                Some(c) if c.is_ascii_hexdigit() => {
                    digits.push(c);
                    self.pos += 1;
                }
                Some(_) => {
                    return Err(ParseError::new(
                        "invalid hexadecimal digit",
                        Span::new(self.pos, self.pos + 1),
                    ))
                }
                None => {
                    return Err(ParseError::new(
                        "hexadecimal literal invalid",
                        Span::new(esc_start, self.pos),
                    ))
                }
            }
        }
        let n = u32::from_str_radix(&digits, 16).unwrap();
        char::from_u32(n).ok_or_else(|| {
            ParseError::new(
                "hexadecimal literal is not a Unicode scalar value",
                Span::new(start, self.pos),
            )
        })
    }

    fn perl_class(&self, kind: char, negate: bool) -> Hir {
        if self.flags.unicode {
            let mut ranges = match kind {
                'd' => unicode::perl_digit(),
                's' => unicode::perl_space(),
                _ => unicode::perl_word(),
            };
            unicode::normalize_ranges(&mut ranges);
            if negate {
                ranges = unicode::negate_ranges(&ranges);
            }
            Hir::UnicodeClass(ranges)
        } else {
            let ranges: Vec<(u8, u8)> = match kind {
                'd' => vec![(b'0', b'9')],
                's' => vec![(0x09, 0x0D), (0x20, 0x20)],
                _ => vec![(b'0', b'9'), (b'A', b'Z'), (b'_', b'_'), (b'a', b'z')],
            };
            let ranges = if negate { negate_bytes(&ranges) } else { ranges };
            Hir::ByteClass(ranges)
        }
    }

    fn parse_unicode_class(&mut self, esc_start: usize, negate: bool) -> Result<Vec<(u32, u32)>> {
        // Cursor sits just after `\p` / `\P`.
        let (name, value, span) = match self.peek() {
            None => {
                return Err(ParseError::new(
                    "incomplete escape sequence, reached end of pattern prematurely",
                    Span::at(self.pos),
                ))
            }
            Some('{') => {
                self.pos += 1;
                let start = self.pos;
                while let Some(c) = self.peek() {
                    if c == '}' {
                        break;
                    }
                    self.pos += 1;
                }
                if self.peek() != Some('}') {
                    return Err(ParseError::new(
                        "unclosed counted repetition",
                        Span::new(start - 1, start),
                    ));
                }
                let body: String = self.chars[start..self.pos].iter().collect();
                self.pos += 1;
                let span = Span::new(esc_start, self.pos);
                let (n, v, neg2) = split_prop(&body);
                (n, v, (span, neg2))
            }
            Some(c) => {
                self.pos += 1;
                (c.to_string(), None, (Span::new(esc_start, self.pos), false))
            }
        };
        let (span, extra_negate) = span;
        let mut ranges = match unicode::unicode_class(&name, value.as_deref()) {
            Some(r) => r,
            None => {
                let msg = if value.is_some() {
                    "Unicode property value not found"
                } else {
                    "Unicode property not found"
                };
                return Err(ParseError::new(msg, span));
            }
        };
        unicode::normalize_ranges(&mut ranges);
        if negate != extra_negate {
            ranges = unicode::negate_ranges(&ranges);
        }
        if self.flags.case_insensitive {
            ranges = unicode::case_fold(&ranges);
        }
        Ok(ranges)
    }

    // ----- character classes -------------------------------------------------

    fn parse_class(&mut self, open: usize) -> Result<Hir> {
        self.nest += 1;
        if self.nest > NEST_LIMIT {
            self.nest -= 1;
            return Err(ParseError::new(
                format!("exceed the maximum number of nested parentheses/brackets ({})", NEST_LIMIT),
                Span::new(open, self.chars.len()),
            ));
        }
        let r = self.parse_class_inner(open);
        self.nest -= 1;
        r
    }

    fn parse_class_inner(&mut self, open: usize) -> Result<Hir> {
        let unicode = self.flags.unicode;
        let negate = self.eat('^');
        // Union of alternating set-operation operands.
        let mut union: Vec<(u32, u32)> = Vec::new();
        let mut first = true;
        loop {
            self.skip_space_in_class();
            match self.peek() {
                None => {
                    return Err(ParseError::new("unclosed character class", Span::new(open, open + 1)))
                }
                Some(']') if !first => {
                    self.pos += 1;
                    break;
                }
                _ => {}
            }
            // `]` as the first member is a literal in the reference engine only
            // when escaped, so treat it as unclosed otherwise.
            if self.peek() == Some(']') && first {
                return Err(ParseError::new(
                    "unclosed character class",
                    Span::new(open, open + 1),
                ));
            }
            first = false;

            // Set operations.
            if self.peek() == Some('&') && self.peek_at(1) == Some('&') {
                self.pos += 2;
                let rhs = self.parse_class_operand(open)?;
                union = unicode::intersect_ranges(&normalized(union), &rhs);
                continue;
            }
            if self.peek() == Some('-') && self.peek_at(1) == Some('-') {
                self.pos += 2;
                let rhs = self.parse_class_operand(open)?;
                union = unicode::difference_ranges(&normalized(union), &rhs);
                continue;
            }
            if self.peek() == Some('~') && self.peek_at(1) == Some('~') {
                self.pos += 2;
                let rhs = self.parse_class_operand(open)?;
                union = unicode::symmetric_difference(&normalized(union), &rhs);
                continue;
            }

            let item = self.parse_class_item(open)?;
            match item {
                ClassItem::Ranges(rs) => union.extend(rs),
                ClassItem::Char(c) => {
                    // Possible range.
                    let after = self.pos;
                    if self.peek() == Some('-')
                        && self.peek_at(1) != Some(']')
                        && self.peek_at(1) != Some('-')
                        && self.peek_at(1).is_some()
                    {
                        self.pos += 1;
                        let hi = self.parse_class_item(open)?;
                        match hi {
                            ClassItem::Char(c2) => {
                                if (c as u32) > (c2 as u32) {
                                    return Err(ParseError::new(
                                        "invalid character class range, the start must be <= the end",
                                        Span::new(after - char_len(c), self.pos),
                                    ));
                                }
                                union.push((c as u32, c2 as u32));
                            }
                            ClassItem::Ranges(_) => {
                                return Err(ParseError::new(
                                    "invalid range boundary, must be a literal",
                                    Span::new(after + 1, self.pos),
                                ));
                            }
                        }
                    } else {
                        union.push((c as u32, c as u32));
                    }
                }
            }
        }
        let mut ranges = normalized(union);
        if self.flags.case_insensitive {
            ranges = unicode::case_fold(&ranges);
        }
        if negate {
            ranges = if unicode {
                unicode::negate_ranges(&ranges)
            } else {
                // Byte semantics: complement within 0..=0xFF.
                let mut out = Vec::new();
                let mut next = 0u32;
                for &(s, e) in &ranges {
                    if s > next {
                        out.push((next, s - 1));
                    }
                    next = next.max(e + 1);
                }
                if next <= 0xFF {
                    out.push((next, 0xFF));
                }
                out
            };
        }
        if unicode {
            Ok(Hir::UnicodeClass(ranges))
        } else {
            let mut br = Vec::new();
            for (s, e) in ranges {
                if s > 0xFF {
                    continue;
                }
                br.push((s as u8, e.min(0xFF) as u8));
            }
            Ok(Hir::ByteClass(br))
        }
    }

    fn skip_space_in_class(&mut self) {
        if self.flags.ignore_whitespace {
            while matches!(self.peek(), Some(c) if c.is_whitespace()) {
                self.pos += 1;
            }
            if self.peek() == Some('#') {
                while let Some(c) = self.peek() {
                    self.pos += 1;
                    if c == '\n' {
                        break;
                    }
                }
                self.skip_space_in_class();
            }
        }
    }

    fn parse_class_operand(&mut self, open: usize) -> Result<Vec<(u32, u32)>> {
        // The right hand side of a set operation: everything up to the closing
        // bracket at this nesting level.
        let mut union: Vec<(u32, u32)> = Vec::new();
        loop {
            self.skip_space_in_class();
            match self.peek() {
                None => {
                    return Err(ParseError::new(
                        "unclosed character class",
                        Span::new(open, open + 1),
                    ))
                }
                Some(']') => break,
                _ => {}
            }
            if (self.peek() == Some('&') && self.peek_at(1) == Some('&'))
                || (self.peek() == Some('-') && self.peek_at(1) == Some('-'))
                || (self.peek() == Some('~') && self.peek_at(1) == Some('~'))
            {
                break;
            }
            let item = self.parse_class_item(open)?;
            match item {
                ClassItem::Ranges(rs) => union.extend(rs),
                ClassItem::Char(c) => {
                    let after = self.pos;
                    if self.peek() == Some('-')
                        && self.peek_at(1) != Some(']')
                        && self.peek_at(1) != Some('-')
                        && self.peek_at(1).is_some()
                    {
                        self.pos += 1;
                        match self.parse_class_item(open)? {
                            ClassItem::Char(c2) => {
                                if (c as u32) > (c2 as u32) {
                                    return Err(ParseError::new(
                                        "invalid character class range, the start must be <= the end",
                                        Span::new(after - char_len(c), self.pos),
                                    ));
                                }
                                union.push((c as u32, c2 as u32));
                            }
                            ClassItem::Ranges(_) => {
                                return Err(ParseError::new(
                                    "invalid range boundary, must be a literal",
                                    Span::new(after + 1, self.pos),
                                ));
                            }
                        }
                    } else {
                        union.push((c as u32, c as u32));
                    }
                }
            }
        }
        Ok(normalized(union))
    }

    fn parse_class_item(&mut self, open: usize) -> Result<ClassItem> {
        match self.peek() {
            None => Err(ParseError::new("unclosed character class", Span::new(open, open + 1))),
            Some('[') => {
                if self.peek_at(1) == Some(':') {
                    return self.parse_posix_class();
                }
                self.pos += 1;
                let sub = self.parse_class(self.pos - 1)?;
                match sub {
                    Hir::UnicodeClass(r) => Ok(ClassItem::Ranges(r)),
                    Hir::ByteClass(r) => {
                        Ok(ClassItem::Ranges(r.into_iter().map(|(s, e)| (s as u32, e as u32)).collect()))
                    }
                    _ => unreachable!(),
                }
            }
            Some('\\') => {
                let start = self.pos;
                // Distinguish class shorthands from literal escapes.
                match self.peek_at(1) {
                    Some('d') | Some('D') | Some('s') | Some('S') | Some('w') | Some('W') => {
                        self.pos += 2;
                        let c = self.chars[start + 1];
                        let negate = c.is_ascii_uppercase();
                        let hir = self.perl_class(c.to_ascii_lowercase(), negate);
                        Ok(ClassItem::Ranges(hir_ranges(&hir)))
                    }
                    Some('p') | Some('P') => {
                        let negate = self.chars[start + 1] == 'P';
                        self.pos += 2;
                        let r = self.parse_unicode_class(start, negate)?;
                        Ok(ClassItem::Ranges(r))
                    }
                    _ => {
                        let c = self.parse_escape_literal(true)?;
                        Ok(ClassItem::Char(c))
                    }
                }
            }
            Some(c) => {
                self.pos += 1;
                Ok(ClassItem::Char(c))
            }
        }
    }

    fn parse_posix_class(&mut self) -> Result<ClassItem> {
        let start = self.pos;
        // `[:` name `:]`
        self.pos += 2;
        let negate = self.eat('^');
        let name_start = self.pos;
        while let Some(c) = self.peek() {
            if c == ':' || c == ']' {
                break;
            }
            self.pos += 1;
        }
        if !(self.peek() == Some(':') && self.peek_at(1) == Some(']')) {
            // Not a POSIX class after all: treat `[` as a literal.
            self.pos = start + 1;
            return Ok(ClassItem::Char('['));
        }
        let name: String = self.chars[name_start..self.pos].iter().collect();
        self.pos += 2;
        match unicode::posix_class(&name) {
            Some(mut r) => {
                unicode::normalize_ranges(&mut r);
                if negate {
                    r = unicode::negate_ranges(&r);
                }
                Ok(ClassItem::Ranges(r))
            }
            None => Err(ParseError::new(
                "unrecognized POSIX character class",
                Span::new(start, self.pos),
            )),
        }
    }
}

enum ClassItem {
    Char(char),
    Ranges(Vec<(u32, u32)>),
}

fn char_len(_c: char) -> usize {
    1
}

fn hir_ranges(h: &Hir) -> Vec<(u32, u32)> {
    match h {
        Hir::UnicodeClass(r) => r.clone(),
        Hir::ByteClass(r) => r.iter().map(|&(s, e)| (s as u32, e as u32)).collect(),
        _ => Vec::new(),
    }
}

fn normalized(mut v: Vec<(u32, u32)>) -> Vec<(u32, u32)> {
    unicode::normalize_ranges(&mut v);
    v
}

fn negate_bytes(v: &[(u8, u8)]) -> Vec<(u8, u8)> {
    let mut out = Vec::new();
    let mut next: u32 = 0;
    for &(s, e) in v {
        if (s as u32) > next {
            out.push((next as u8, s - 1));
        }
        next = next.max(e as u32 + 1);
    }
    if next <= 0xFF {
        out.push((next as u8, 0xFF));
    }
    out
}

/// Split `\p{...}` body into property name, optional value and negation.
fn split_prop(body: &str) -> (String, Option<String>, bool) {
    let (neg, body) = match body.strip_prefix('^') {
        Some(rest) => (true, rest),
        None => (false, body),
    };
    for sep in ['=', ':'] {
        if let Some(i) = body.find(sep) {
            return (body[..i].to_string(), Some(body[i + 1..].to_string()), neg);
        }
    }
    (body.to_string(), None, neg)
}

fn push_item(items: &mut Vec<Hir>, h: Hir) {
    // Coalesce adjacent literals so that plain strings compile compactly.
    if let (Some(Hir::Literal(prev)), Hir::Literal(next)) = (items.last_mut(), &h) {
        prev.extend_from_slice(next);
        return;
    }
    if matches!(h, Hir::Empty) {
        return;
    }
    items.push(h);
}

/// Collapse an alternation of single scalar values into one class, mirroring the
/// reference engine's HIR optimisation (it affects program size).
fn simplify_alt(branches: Vec<Hir>) -> Hir {
    let mut ranges: Vec<(u32, u32)> = Vec::new();
    let mut all_single = true;
    for b in &branches {
        match b {
            Hir::Literal(bytes) => match std::str::from_utf8(bytes) {
                Ok(s) if s.chars().count() == 1 => {
                    let c = s.chars().next().unwrap();
                    ranges.push((c as u32, c as u32));
                }
                _ => {
                    all_single = false;
                    break;
                }
            },
            Hir::UnicodeClass(r) => ranges.extend(r.iter().copied()),
            _ => {
                all_single = false;
                break;
            }
        }
    }
    if all_single && !ranges.is_empty() {
        return Hir::UnicodeClass(normalized(ranges));
    }
    Hir::Alt(branches)
}

fn is_capture_char(c: char, first: bool) -> bool {
    c == '_'
        || (!first && (c.is_ascii_digit() || c == '.' || c == '[' || c == ']'))
        || c.is_alphabetic()
}

// ----- error rendering -------------------------------------------------------

/// Render a parse error the way the reference engine does.
pub fn render_error(pattern: &str, err: &ParseError) -> String {
    let lines: Vec<&str> = split_lines(pattern);
    let mut spans = vec![err.span];
    if let Some(s) = err.span2 {
        spans.push(s);
    }
    // Map spans onto (line, column) pairs.
    let positions: Vec<(Pos, Pos)> = spans
        .iter()
        .map(|s| (position_of(pattern, s.start), position_of(pattern, s.end)))
        .collect();

    let mut out = String::from("regex parse error:\n");
    let multiline = pattern.contains('\n');
    let divider: String = std::iter::repeat('~').take(79).collect();
    if multiline {
        out.push_str(&divider);
        out.push('\n');
    }
    for (i, line) in lines.iter().enumerate() {
        let lineno = i + 1;
        out.push_str("    ");
        out.push_str(line);
        out.push('\n');
        let notes: Vec<(usize, usize)> = positions
            .iter()
            .filter(|(s, e)| s.line == lineno && e.line == lineno)
            .map(|(s, e)| (s.column, e.column))
            .collect();
        if !notes.is_empty() {
            let mut buf: Vec<char> = Vec::new();
            for (sc, ec) in notes {
                let n = if sc == ec { 1 } else { ec - sc };
                while buf.len() + 1 < sc {
                    buf.push(' ');
                }
                for _ in 0..n {
                    buf.push('^');
                }
            }
            out.push_str("    ");
            out.extend(buf);
            out.push('\n');
        }
    }
    if multiline {
        out.push_str(&divider);
        out.push('\n');
        let mut notes = Vec::new();
        for (s, e) in positions.iter() {
            if s.line != e.line {
                notes.push(format!(
                    "on line {} (column {}) through line {} (column {})",
                    s.line,
                    s.column,
                    e.line,
                    e.column.saturating_sub(1)
                ));
            }
        }
        if !notes.is_empty() {
            out.push_str(&notes.join("\n"));
            out.push('\n');
        }
    }
    out.push_str("error: ");
    out.push_str(&err.msg);
    out
}

struct Pos {
    line: usize,
    column: usize,
}

fn position_of(pattern: &str, char_index: usize) -> Pos {
    let mut line = 1usize;
    let mut column = 1usize;
    for (i, c) in pattern.chars().enumerate() {
        if i == char_index {
            return Pos { line, column };
        }
        if c == '\n' {
            line += 1;
            column = 1;
        } else {
            column += 1;
        }
    }
    Pos { line, column }
}

fn split_lines(pattern: &str) -> Vec<&str> {
    if pattern.is_empty() {
        return vec![""];
    }
    let mut v: Vec<&str> = pattern.split('\n').collect();
    if pattern.ends_with('\n') {
        v.pop();
    }
    v
}

