//! Compilation of the parsed HIR into a byte-oriented NFA program.

use super::parse::{Hir, Look};
use super::utf8::{utf8_sequences, ByteRange, Utf8Seq};
use std::collections::HashMap;

#[derive(Clone, Debug)]
pub enum Inst {
    /// Match one byte in any of `ranges`, then continue at `next`.
    Sparse { ranges: Vec<(u8, u8)>, next: usize },
    /// Try each alternative in order.
    Split { alts: Vec<usize> },
    Jump(usize),
    Save { slot: usize, next: usize },
    Look { look: Look, next: usize },
    Match,
    Fail,
}

pub struct Program {
    pub insts: Vec<Inst>,
    pub start: usize,
    pub nslots: usize,
}

/// Byte budget mirroring the reference engine's compiled-size accounting.
pub const SIZE_LIMIT: u64 = 10_485_760;
const STATE: u64 = 32;
const PER_RANGE: u64 = 8;
const PER_ALT: u64 = 4;
const BASE: u64 = 224;

/// Estimate the compiled size, in the same units the reference engine reports.
pub fn estimate_size(hir: &Hir) -> u64 {
    BASE.saturating_add(est(hir))
}

fn est(hir: &Hir) -> u64 {
    match hir {
        Hir::Empty => 0,
        Hir::Literal(bytes) => STATE.saturating_mul(bytes.len() as u64),
        Hir::ByteClass(rs) => STATE + PER_RANGE * rs.len() as u64 + STATE,
        Hir::UnicodeClass(rs) => utf8_cost(rs),
        Hir::Look(_) => STATE,
        Hir::Group { index, sub } => {
            let inner = est(sub);
            if index.is_some() {
                inner.saturating_add(2 * STATE)
            } else {
                inner
            }
        }
        Hir::Concat(v) => v.iter().map(est).fold(0u64, |a, b| a.saturating_add(b)),
        Hir::Alt(v) => {
            let inner = v.iter().map(est).fold(0u64, |a, b| a.saturating_add(b));
            inner
                .saturating_add(STATE + PER_ALT * v.len() as u64)
                .saturating_add(STATE)
        }
        Hir::Repeat { min, max, sub, .. } => {
            let inner = est(sub);
            let opt = inner.saturating_add(STATE + 2 * PER_ALT).saturating_add(STATE);
            match max {
                Some(max) => {
                    let required = inner.saturating_mul(*min as u64);
                    let optional = opt.saturating_mul((*max - *min) as u64);
                    required.saturating_add(optional)
                }
                None => inner
                    .saturating_mul(*min as u64)
                    .saturating_add(opt)
                    .saturating_add(STATE),
            }
        }
    }
}

fn utf8_cost(ranges: &[(u32, u32)]) -> u64 {
    let seqs = all_sequences(ranges);
    if seqs.is_empty() {
        return STATE;
    }
    let mut cost = STATE; // trailing join
    let mut cache: HashMap<Vec<Utf8Seq>, ()> = HashMap::new();
    cost += group_cost(&seqs, &mut cache);
    cost
}

fn all_sequences(ranges: &[(u32, u32)]) -> Vec<Utf8Seq> {
    let mut seqs = Vec::new();
    for &(s, e) in ranges {
        utf8_sequences(s, e, &mut seqs);
    }
    seqs
}

/// Cost of the byte automaton for a set of sequences, sharing common suffixes.
fn group_cost(seqs: &[Utf8Seq], cache: &mut HashMap<Vec<Utf8Seq>, ()>) -> u64 {
    let groups = group_by_tail(seqs);
    let mut cost = 0u64;
    if groups.len() > 1 {
        cost += STATE + PER_ALT * groups.len() as u64;
    }
    for (heads, tails) in groups {
        cost += STATE + PER_RANGE * heads.len() as u64;
        if !tails.is_empty() && !tails.iter().all(|t| t.is_empty()) {
            let key = tails.clone();
            if cache.insert(key, ()).is_none() {
                cost += group_cost(&tails, cache);
            }
        }
    }
    cost
}

type TailGroup = (Vec<(u8, u8)>, Vec<Utf8Seq>);

/// Group sequences that share an identical tail, merging their leading ranges.
fn group_by_tail(seqs: &[Utf8Seq]) -> Vec<TailGroup> {
    let mut groups: Vec<(Vec<ByteRange>, Vec<(u8, u8)>)> = Vec::new();
    for s in seqs {
        if s.is_empty() {
            continue;
        }
        let head = (s[0].start, s[0].end);
        let tail: Vec<ByteRange> = s[1..].to_vec();
        match groups.iter_mut().find(|(t, _)| *t == tail) {
            Some((_, heads)) => {
                if !heads.contains(&head) {
                    heads.push(head)
                }
            }
            None => groups.push((tail, vec![head])),
        }
    }
    groups
        .into_iter()
        .map(|(tail, mut heads)| {
            heads.sort_unstable();
            let tails = if tail.is_empty() { Vec::new() } else { vec![tail] };
            (heads, tails)
        })
        .collect()
}

pub struct Compiler {
    insts: Vec<Inst>,
    /// Cache of compiled UTF-8 suffix automata, keyed by suffix and successor.
    suffix_cache: HashMap<(Vec<ByteRange>, usize), usize>,
}

impl Compiler {
    pub fn compile(hir: &Hir, ngroups: u32) -> Program {
        let mut c = Compiler { insts: Vec::new(), suffix_cache: HashMap::new() };
        let match_pc = c.push(Inst::Match);
        let end0 = c.push(Inst::Save { slot: 1, next: match_pc });
        let body = c.node(hir, end0);
        let start = c.push(Inst::Save { slot: 0, next: body });
        Program { insts: c.insts, start, nslots: 2 * (ngroups as usize + 1) }
    }

    fn push(&mut self, inst: Inst) -> usize {
        self.insts.push(inst);
        self.insts.len() - 1
    }

    /// Compile `hir` so that a successful match continues at `next`.
    fn node(&mut self, hir: &Hir, next: usize) -> usize {
        match hir {
            Hir::Empty => next,
            Hir::Literal(bytes) => {
                let mut pc = next;
                for &b in bytes.iter().rev() {
                    pc = self.push(Inst::Sparse { ranges: vec![(b, b)], next: pc });
                }
                pc
            }
            Hir::ByteClass(rs) => {
                if rs.is_empty() {
                    return self.push(Inst::Fail);
                }
                self.push(Inst::Sparse { ranges: rs.clone(), next })
            }
            Hir::UnicodeClass(rs) => self.unicode_class(rs, next),
            Hir::Look(l) => self.push(Inst::Look { look: *l, next }),
            Hir::Group { index, sub } => match index {
                Some(i) => {
                    let close = self.push(Inst::Save { slot: 2 * (*i as usize) + 1, next });
                    let inner = self.node(sub, close);
                    self.push(Inst::Save { slot: 2 * (*i as usize), next: inner })
                }
                None => self.node(sub, next),
            },
            Hir::Concat(v) => {
                let mut pc = next;
                for h in v.iter().rev() {
                    pc = self.node(h, pc);
                }
                pc
            }
            Hir::Alt(v) => {
                let alts: Vec<usize> = v.iter().map(|h| self.node(h, next)).collect();
                self.push(Inst::Split { alts })
            }
            Hir::Repeat { min, max, greedy, sub } => self.repeat(*min, *max, *greedy, sub, next),
        }
    }

    fn repeat(
        &mut self,
        min: u32,
        max: Option<u32>,
        greedy: bool,
        sub: &Hir,
        next: usize,
    ) -> usize {
        match max {
            None => {
                if min == 0 {
                    // sub*
                    let split = self.push(Inst::Split { alts: Vec::new() });
                    let body = self.node(sub, split);
                    self.insts[split] = Inst::Split {
                        alts: if greedy { vec![body, next] } else { vec![next, body] },
                    };
                    split
                } else {
                    // sub{min-1} sub+
                    let split = self.push(Inst::Split { alts: Vec::new() });
                    let body = self.node(sub, split);
                    self.insts[split] = Inst::Split {
                        alts: if greedy { vec![body, next] } else { vec![next, body] },
                    };
                    let mut pc = body;
                    for _ in 1..min {
                        pc = self.node(sub, pc);
                    }
                    pc
                }
            }
            Some(max) => {
                if max == 0 {
                    return next;
                }
                // (max - min) optional copies, innermost first.
                let mut pc = next;
                for _ in min..max {
                    let inner = self.node(sub, pc);
                    pc = self.push(Inst::Split {
                        alts: if greedy { vec![inner, pc] } else { vec![pc, inner] },
                    });
                }
                for _ in 0..min {
                    pc = self.node(sub, pc);
                }
                pc
            }
        }
    }

    fn unicode_class(&mut self, ranges: &[(u32, u32)], next: usize) -> usize {
        let seqs = all_sequences(ranges);
        if seqs.is_empty() {
            return self.push(Inst::Fail);
        }
        self.seq_group(&seqs, next)
    }

    fn seq_group(&mut self, seqs: &[Utf8Seq], next: usize) -> usize {
        let groups = group_by_tail(seqs);
        let mut alts = Vec::with_capacity(groups.len());
        for (heads, tails) in groups {
            let cont = if tails.is_empty() {
                next
            } else {
                self.suffix(&tails[0], next)
            };
            alts.push(self.push(Inst::Sparse { ranges: heads, next: cont }));
        }
        if alts.len() == 1 {
            alts[0]
        } else {
            self.push(Inst::Split { alts })
        }
    }

    fn suffix(&mut self, seq: &[ByteRange], next: usize) -> usize {
        let key = (seq.to_vec(), next);
        if let Some(&pc) = self.suffix_cache.get(&key) {
            return pc;
        }
        let mut pc = next;
        for r in seq.iter().rev() {
            pc = self.push(Inst::Sparse { ranges: vec![(r.start, r.end)], next: pc });
        }
        self.suffix_cache.insert(key, pc);
        pc
    }
}

