//! Thompson NFA simulation with thread priority, giving leftmost-first match
//! semantics in linear time.

use super::compile::{Inst, Program};
use super::parse::Look;
use super::unicode;
use std::rc::Rc;

type Caps = Rc<Vec<Option<usize>>>;

struct Thread {
    pc: usize,
    caps: Caps,
}

struct ThreadList {
    dense: Vec<Thread>,
    /// Generation marker per instruction, avoiding a clear pass.
    seen: Vec<u32>,
    gen: u32,
}

impl ThreadList {
    fn new(n: usize) -> Self {
        ThreadList { dense: Vec::with_capacity(16), seen: vec![0; n], gen: 0 }
    }
    fn clear(&mut self) {
        self.dense.clear();
        self.gen += 1;
    }
    fn mark(&mut self, pc: usize) -> bool {
        if self.seen[pc] == self.gen {
            false
        } else {
            self.seen[pc] = self.gen;
            true
        }
    }
}

pub struct Machine<'p> {
    prog: &'p Program,
    clist: ThreadList,
    nlist: ThreadList,
    /// Bytes that can begin a match, when that can be determined.
    start_bytes: Option<Box<[bool; 256]>>,
    /// Literal prefix every match must begin with.
    prefix: Vec<u8>,
}

impl<'p> Machine<'p> {
    pub fn new(prog: &'p Program) -> Self {
        let n = prog.insts.len();
        let mut m = Machine {
            prog,
            clist: ThreadList::new(n),
            nlist: ThreadList::new(n),
            start_bytes: None,
            prefix: Vec::new(),
        };
        m.start_bytes = m.compute_start_bytes();
        m.prefix = m.compute_prefix();
        m
    }

    /// Conservatively collect the bytes a match may start with. Returns `None`
    /// when a match can begin without consuming a byte, or when a look-around
    /// assertion makes the answer unclear.
    fn compute_start_bytes(&self) -> Option<Box<[bool; 256]>> {
        let mut set = Box::new([false; 256]);
        let mut stack = vec![self.prog.start];
        let mut seen = vec![false; self.prog.insts.len()];
        while let Some(pc) = stack.pop() {
            if seen[pc] {
                continue;
            }
            seen[pc] = true;
            match &self.prog.insts[pc] {
                Inst::Sparse { ranges, .. } => {
                    for &(s, e) in ranges {
                        for b in s..=e {
                            set[b as usize] = true;
                        }
                    }
                }
                Inst::Split { alts } => stack.extend(alts.iter().copied()),
                Inst::Jump(n) => stack.push(*n),
                Inst::Save { next, .. } => stack.push(*next),
                Inst::Look { look, next } => {
                    // Assertions that cannot be decided without context force
                    // the general path, except for text/line anchors which do
                    // not consume input and so do not restrict the first byte.
                    match look {
                        Look::StartText
                        | Look::EndText
                        | Look::StartLine
                        | Look::EndLine
                        | Look::StartCrLf
                        | Look::EndCrLf => stack.push(*next),
                        _ => return None,
                    }
                }
                Inst::Match => return None,
                Inst::Fail => {}
            }
        }
        Some(set)
    }

    /// The literal byte string every match must begin with, if any.
    fn compute_prefix(&self) -> Vec<u8> {
        let mut out = Vec::new();
        let mut pc = self.prog.start;
        loop {
            match &self.prog.insts[pc] {
                Inst::Save { next, .. } => pc = *next,
                Inst::Sparse { ranges, next } if ranges.len() == 1 && ranges[0].0 == ranges[0].1 => {
                    out.push(ranges[0].0);
                    pc = *next;
                    if out.len() >= 128 {
                        break;
                    }
                }
                _ => break,
            }
        }
        out
    }

    fn candidate(&self, hay: &[u8], from: usize) -> Option<usize> {
        if self.prefix.len() > 1 {
            return find_sub(hay, &self.prefix, from);
        }
        match &self.start_bytes {
            None => Some(from),
            Some(set) => {
                let mut i = from;
                while i < hay.len() {
                    if set[hay[i] as usize] {
                        return Some(i);
                    }
                    i += 1;
                }
                // An empty haystack tail can still match if the program only
                // needs assertions, which `compute_start_bytes` rules out.
                None
            }
        }
    }

    /// Search for the leftmost-first match at or after `at`.
    pub fn search(&mut self, hay: &[u8], at: usize) -> Option<Vec<Option<usize>>> {
        let start_at = match self.candidate(hay, at) {
            Some(p) => p,
            None => return None,
        };
        let mut matched: Option<Caps> = None;
        self.clist.clear();
        self.nlist.clear();
        let mut pos = start_at;
        let empty: Caps = Rc::new(vec![None; self.prog.nslots]);
        loop {
            if matched.is_none() {
                if self.clist.dense.is_empty() && pos > start_at {
                    // No live threads: jump straight to the next candidate.
                    match self.candidate(hay, pos) {
                        Some(p) if p > pos => {
                            pos = p;
                            self.clist.clear();
                        }
                        Some(_) => {}
                        None => break,
                    }
                }
                let start = self.prog.start;
                add_thread(self.prog, &mut self.clist, start, pos, hay, empty.clone());
            }
            if self.clist.dense.is_empty() {
                break;
            }
            let n = self.clist.dense.len();
            let byte = hay.get(pos).copied();
            for i in 0..n {
                let (pc, caps) = {
                    let t = &self.clist.dense[i];
                    (t.pc, t.caps.clone())
                };
                match &self.prog.insts[pc] {
                    Inst::Sparse { ranges, next } => {
                        if let Some(b) = byte {
                            if ranges.iter().any(|&(s, e)| b >= s && b <= e) {
                                let next = *next;
                                add_thread(
                                    self.prog,
                                    &mut self.nlist,
                                    next,
                                    pos + 1,
                                    hay,
                                    caps,
                                );
                            }
                        }
                    }
                    Inst::Match => {
                        matched = Some(caps);
                        break;
                    }
                    _ => {}
                }
            }
            if pos >= hay.len() {
                break;
            }
            pos += 1;
            std::mem::swap(&mut self.clist, &mut self.nlist);
            self.nlist.clear();
        }
        matched.map(|c| (*c).clone())
    }
}

fn add_thread(
    prog: &Program,
    list: &mut ThreadList,
    pc: usize,
    pos: usize,
    hay: &[u8],
    caps: Caps,
) {
    if !list.mark(pc) {
        return;
    }
    match &prog.insts[pc] {
        Inst::Jump(n) => add_thread(prog, list, *n, pos, hay, caps),
        Inst::Split { alts } => {
            for &a in alts {
                add_thread(prog, list, a, pos, hay, caps.clone());
            }
        }
        Inst::Save { slot, next } => {
            let slot = *slot;
            let next = *next;
            if slot < caps.len() {
                let mut c = caps;
                Rc::make_mut(&mut c)[slot] = Some(pos);
                add_thread(prog, list, next, pos, hay, c);
            } else {
                add_thread(prog, list, next, pos, hay, caps);
            }
        }
        Inst::Look { look, next } => {
            if look_matches(*look, hay, pos) {
                add_thread(prog, list, *next, pos, hay, caps);
            }
        }
        Inst::Fail => {}
        Inst::Sparse { .. } | Inst::Match => {
            list.dense.push(Thread { pc, caps });
        }
    }
}

fn decode_last(hay: &[u8], pos: usize) -> Option<char> {
    if pos == 0 {
        return None;
    }
    let mut start = pos.saturating_sub(1);
    let lo = pos.saturating_sub(4);
    while start > lo && (hay[start] & 0xC0) == 0x80 {
        start -= 1;
    }
    std::str::from_utf8(&hay[start..pos]).ok().and_then(|s| s.chars().next_back())
}

fn decode_next(hay: &[u8], pos: usize) -> Option<char> {
    if pos >= hay.len() {
        return None;
    }
    let end = (pos + 4).min(hay.len());
    for e in (pos + 1..=end).rev() {
        if let Ok(s) = std::str::from_utf8(&hay[pos..e]) {
            if let Some(c) = s.chars().next() {
                return Some(c);
            }
        }
    }
    None
}

fn is_word_before(hay: &[u8], pos: usize, uni: bool) -> bool {
    if uni {
        decode_last(hay, pos).map(unicode::is_word_char).unwrap_or(false)
    } else {
        pos > 0 && unicode::is_word_byte(hay[pos - 1])
    }
}

fn is_word_after(hay: &[u8], pos: usize, uni: bool) -> bool {
    if uni {
        decode_next(hay, pos).map(unicode::is_word_char).unwrap_or(false)
    } else {
        pos < hay.len() && unicode::is_word_byte(hay[pos])
    }
}

fn look_matches(look: Look, hay: &[u8], pos: usize) -> bool {
    match look {
        Look::StartText => pos == 0,
        Look::EndText => pos == hay.len(),
        Look::StartLine => pos == 0 || hay[pos - 1] == b'\n',
        Look::EndLine => pos == hay.len() || hay[pos] == b'\n',
        Look::StartCrLf => {
            pos == 0
                || hay[pos - 1] == b'\n'
