        Look::WordUnicode => is_word_before(hay, pos, true) != is_word_after(hay, pos, true),
        Look::NotWordUnicode => is_word_before(hay, pos, true) == is_word_after(hay, pos, true),
        Look::WordStartAscii => !is_word_before(hay, pos, false) && is_word_after(hay, pos, false),
        Look::WordEndAscii => is_word_before(hay, pos, false) && !is_word_after(hay, pos, false),
        Look::WordStartUnicode => !is_word_before(hay, pos, true) && is_word_after(hay, pos, true),
        Look::WordEndUnicode => is_word_before(hay, pos, true) && !is_word_after(hay, pos, true),
        Look::WordStartHalfAscii => !is_word_before(hay, pos, false),
        Look::WordEndHalfAscii => !is_word_after(hay, pos, false),
        Look::WordStartHalfUnicode => !is_word_before(hay, pos, true),
        Look::WordEndHalfUnicode => !is_word_after(hay, pos, true),
