//! A small regular expression engine with the same dialect and match semantics
//! as the one the reference tool uses: byte oriented, Unicode aware, leftmost
//! first, linear time.

mod compile;
mod parse;
mod unicode;
mod utf8;
mod vm;

pub use parse::Flags;

use compile::{estimate_size, Compiler, Program, SIZE_LIMIT};
use parse::Parser;
use vm::Machine;

pub enum Error {
    /// Already rendered as a caret diagram.
    Syntax(String),
    CompiledTooBig(u64),
}

impl std::fmt::Display for Error {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Error::Syntax(s) => write!(f, "{}", s),
            Error::CompiledTooBig(n) => {
                write!(f, "Compiled regex exceeds size limit of {} bytes.", n)
            }
        }
    }
}

pub struct Regex {
    prog: Program,
    names: Vec<(String, u32)>,
}

/// Slots recorded for a match: `2*i` and `2*i+1` bound group `i`.
pub struct Captures<'h> {
    hay: &'h [u8],
    slots: Vec<Option<usize>>,
}

impl<'h> Captures<'h> {
    pub fn get(&self, i: usize) -> Option<&'h [u8]> {
        let s = (*self.slots.get(2 * i)?)?;
        let e = (*self.slots.get(2 * i + 1)?)?;
        Some(&self.hay[s..e])
    }
}

impl Regex {
    pub fn new(pattern: &str, flags: Flags) -> Result<Regex, Error> {
        let parsed = Parser::new(pattern, flags)
            .parse()
            .map_err(|e| Error::Syntax(parse::render_error(pattern, &e)))?;
        if estimate_size(&parsed.hir) > SIZE_LIMIT {
            return Err(Error::CompiledTooBig(SIZE_LIMIT));
        }
        let prog = Compiler::compile(&parsed.hir, parsed.group_count);
        Ok(Regex { prog, names: parsed.names })
    }

    pub fn name_index(&self, name: &str) -> Option<u32> {
        self.names.iter().find(|(n, _)| n == name).map(|(_, i)| *i)
    }

    /// Replace up to `limit` matches (0 meaning all). Returns `None` when
    /// nothing matched.
    pub fn replacen<F>(&self, hay: &[u8], limit: usize, mut rep: F) -> Option<Vec<u8>>
    where
        F: FnMut(&Captures<'_>, &mut Vec<u8>),
    {
        let mut machine = Machine::new(&self.prog);
        let mut out: Vec<u8> = Vec::new();
        let mut last_end = 0usize;
        let mut last_match_end: Option<usize> = None;
        let mut count = 0usize;
        let mut search_from = 0usize;
        loop {
            if limit != 0 && count >= limit {
                break;
            }
            if search_from > hay.len() {
                break;
            }
            let slots = match machine.search(hay, search_from) {
                None => break,
                Some(s) => s,
            };
            let (s, e) = match (slots[0], slots[1]) {
                (Some(s), Some(e)) => (s, e),
                _ => break,
            };
            if s == e {
                search_from = e + 1;
                if Some(e) == last_match_end {
                    continue;
                }
            } else {
                search_from = e;
            }
            last_match_end = Some(e);
            if count == 0 {
                out.reserve(hay.len() + 16);
            }
            out.extend_from_slice(&hay[last_end..s]);
            rep(&Captures { hay, slots }, &mut out);
            last_end = e;
            count += 1;
        }
        if count == 0 {
            return None;
        }
        out.extend_from_slice(&hay[last_end..]);
        Some(out)
    }
}

